// Verifies the HMAC signature and the timestamp. Never throws: anything wrong means { valid: false }.
const reject = () => [{ json: { valid: false } }];
try {
  const headers = $input.first().json.headers || {};
  const signature = String(headers['x-lendloop-signature'] || '');
  const timestamp = String(headers['x-lendloop-timestamp'] || '');
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) return reject();
  if (!/^[0-9a-f]{64}$/.test(signature) || !/^[0-9]{10,16}$/.test(timestamp)) return reject();
  if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) return reject();

  // The signature covers the exact bytes Convex sent, so hash the raw body, not parsed JSON.
  const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  const crypto = require('crypto');
  const expected = crypto.createHmac('sha256', secret).update(timestamp + '.').update(raw).digest();
  if (!crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex'))) return reject();

  return [{ json: { valid: true, ...JSON.parse(raw.toString('utf8')) } }];
} catch (error) {
  return reject();
}

// Logged mock notification. Uses only the fields in the payload.
const p = $input.first().json;
if (!['pending', 'approved', 'pickedUp', 'declined', 'returned', 'cancelled'].includes(p.status)) {
  throw new Error('Unknown request status: ' + p.status);
}
if (p.status === 'cancelled' && !['owner', 'borrower'].includes(p.cancelledBy)) {
  throw new Error('Unknown cancelledBy: ' + p.cancelledBy);
}
const dates = p.startDate === p.endDate ? p.startDate : p.startDate + ' to ' + p.endDate;
const owner = p.ownerName || 'the owner';
const borrower = p.borrowerName || 'the borrower';
let to;
let text;
if (p.status === 'pending') {
  to = owner;
  text = borrower + ' asked to borrow your ' + p.toolName + ' (' + dates + ').';
} else if (p.status === 'pickedUp') {
  to = owner;
  text = borrower + ' confirmed they received your ' + p.toolName + ' (' + dates + ').';
} else if (p.status === 'cancelled' && p.cancelledBy === 'borrower') {
  to = owner;
  text = borrower + ' cancelled their request for your ' + p.toolName + ' (' + dates + ').';
} else {
  to = borrower;
  const what = { approved: 'was approved', declined: 'was declined', returned: 'was marked as returned', cancelled: 'was cancelled by the owner' }[p.status];
  text = 'Your request for ' + p.toolName + ' (' + dates + ') ' + what + '.';
}
console.log('[notification] to ' + to + ': ' + text);
return [{ json: { to, text } }];
